<?php
namespace App\Policies;
use App\Models\{ActualCost,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class ActualCostPolicy { use HandlesAuthorization,CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_actual::cost');} public function view(User $u,ActualCost $r):bool{return $this->canForRecord($u,'view_actual::cost',$r);} public function create(User $u):bool{return $u->can('create_actual::cost');} public function update(User $u,ActualCost $r):bool{return $r->status==='draft'&&$this->canForRecord($u,'update_actual::cost',$r);} public function delete(User $u,ActualCost $r):bool{return $r->status==='draft'&&$this->canForRecord($u,'delete_actual::cost',$r);} public function deleteAny(User $u):bool{return false;} public function forceDelete(User $u,ActualCost $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function restore(User $u,ActualCost $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function replicate(User $u,ActualCost $r):bool{return false;} public function reorder(User $u):bool{return false;} public function submit(User $u,ActualCost $r):bool{return $this->canForRecord($u,'submit_actual_cost',$r);} public function approve(User $u,ActualCost $r):bool{return $this->canForRecord($u,'approve_actual_cost',$r);} public function correct(User $u,ActualCost $r):bool{return $this->canForRecord($u,'create_actual_cost_correction',$r);} }
